import type { PluginInitContext, PluginRouteResult } from 'typecho/plugin-sdk';
import { loadPluginConfig } from '@/lib/plugin';
import katexCss from './client/dist/katex-inline.css?raw';
import enhancerCss from './client/rehype-styles.css?inline';

// Generated by this plugin's own build script inside client/dist.
// The route below serves these strings; no browser resource is written to public/.
import rehypeRuntime from './client/dist/rehype-runtime.js?raw';
import mathRuntime from './client/dist/math-runtime.js?raw';
import mermaidRuntime from './client/dist/mermaid-runtime.js?raw';
import highlightRuntime from './client/dist/highlight-runtime.js?raw';
import blurhashRuntime from './client/dist/blurhash-runtime.js?raw';

const ASSET_PREFIX = '/__plugin-assets/typecho-plugin-markdown-rehype-oxn/';

const runtimeAssets: Record<string, string> = {
  'rehype-runtime.js': rehypeRuntime,
  'math-runtime.js': mathRuntime,
  'mermaid-runtime.js': mermaidRuntime,
  'highlight-runtime.js': highlightRuntime,
  'blurhash-runtime.js': blurhashRuntime,
  'katex-inline.css': katexCss,
  'rehype-styles.css': enhancerCss,
};

type RouteExtra = { path?: string; request?: Request };

function enabled(value: unknown): boolean {
  return value === true || value === 1 || value === '1' || value === 'true' || value === 'on';
}
function featureConfig(options: Record<string, unknown> | undefined, pluginId: string) {
  const saved = loadPluginConfig(options || {}, pluginId);
  return {
    math: enabled(saved.enableMath),
    mermaid: enabled(saved.enableMermaid),
    highlight: enabled(saved.enableHighlight),
    blurhash: enabled(saved.enableBlurhash),
    lazyImages: enabled(saved.enableImageLazyLoading),
    loadingMode: saved.resourceLoadingMode === 'full' ? 'full' : 'ondemand',
  };
}
/** Preserve TeX row separators before the host's ordinary Markdown parser. */
function protectMathSegment(source: string): string {
  const codeAware = source.split(/(\x60+[\s\S]*?\x60+)/g);
  return codeAware.map((part, codeIndex) => {
    if (codeIndex % 2 === 1) return part;
    const mathBlocks = part.split(/(\$\$[\s\S]*?\$\$|\\\[[\s\S]*?\\\]|\\\([\s\S]*?\\\)|\$(?!\$)[^$\r\n]+\$(?!\$))/g);
    return mathBlocks.map((formula, mathIndex) => mathIndex % 2 === 1
      ? formula.split('\\').join('&#92;')
      : formula).join('');
  }).join('');
}


/** Defer the original image request before the browser parses article-body images. */
function deferBlurhashImages(html: string): string {
  const transparent = 'data:image/gif;base64,R0lGODlhAQABAAD/ACwAAAAAAQABAAACADs=';
  const rootPattern = /<([a-z][\w:-]*)\b[^>]*\bitemprop=(["'])articleBody\2[^>]*>/gi;
  const decode = (value: string) => {
    try { return decodeURIComponent(value); } catch { return value.replace(/%([0-9a-f]{2})/gi, (_m, hex: string) => String.fromCharCode(parseInt(hex, 16))); }
  };
  let output = '';
  let cursor = 0;
  let root: RegExpExecArray | null;
  while ((root = rootPattern.exec(html))) {
    const tag = root[1];
    const contentStart = rootPattern.lastIndex;
    const tagPattern = new RegExp('</?' + tag + '\\b[^>]*>', 'gi');
    tagPattern.lastIndex = contentStart;
    let depth = 1;
    let end = html.length;
    let token: RegExpExecArray | null;
    while ((token = tagPattern.exec(html))) {
      if (/^<\//.test(token[0])) depth--;
      else if (!/\/>$/.test(token[0])) depth++;
      if (depth === 0) { end = token.index; break; }
    }
    let body = html.slice(contentStart, end);
    body = body.replace(/<img\b[^>]*>/gi, tagHtml => {
      const source = tagHtml.match(/\bsrc=(["'])(.*?)\1/i);
      if (!source || !/#blurhash=/i.test(source[2])) return tagHtml;
      const original = source[2];
      const fragment = original.replace(/&amp;/gi, '&').slice(original.indexOf('#') + 1);
      const params = new Map<string, string>();
      for (const part of fragment.split('&')) {
        const equal = part.indexOf('=');
        if (equal < 0) continue;
        params.set(decode(part.slice(0, equal)), decode(part.slice(equal + 1)));
      }
      if (!params.get('blurhash')) return tagHtml;
      let updated = tagHtml.replace(source[0], 'src="' + transparent + '" data-oxn-blurhash-src="' + original.replace(/&/g, '&amp;').replace(/"/g, '&quot;') + '"');
      if (params.has('width') && !/\bwidth=/i.test(updated) && /^\d+$/.test(params.get('width')!)) updated = updated.replace(/>$/, ' width="' + params.get('width') + '">');
      if (params.has('height') && !/\bheight=/i.test(updated) && /^\d+$/.test(params.get('height')!)) updated = updated.replace(/>$/, ' height="' + params.get('height') + '">');
      return updated;
    });
    output += html.slice(cursor, contentStart) + body;
    cursor = end;
    rootPattern.lastIndex = end;
  }
  return output + html.slice(cursor);
}
function protectMathSource(source: string): string {
  const segments = source.split(/(^\x60{3,}[^\n]*\n[\s\S]*?^\x60{3,}[ \t]*$|^~{3,}[^\n]*\n[\s\S]*?^~{3,}[ \t]*$)/gm);
  return segments.map((part, index) => index % 2 === 1 ? part : protectMathSegment(part)).join('');
}

export default function init({ addHook, pluginId }: PluginInitContext): void {
  // Keep TeX row separators intact; the host still owns Markdown parsing.
  addHook('content:markdown', pluginId, (source: string) => protectMathSource(source), 1000);

  // Serve generated runtime files from this plugin's own build directory.
  // The public/ directory is deliberately not used by this plugin.
  addHook('route:request', pluginId, (result: PluginRouteResult, extra?: RouteExtra) => {
    if (result?.handled || !extra?.path) return result;
    if (!extra.path.startsWith(ASSET_PREFIX)) return result;
    if (extra.request?.method !== 'GET' && extra.request?.method !== 'HEAD') {
      return {
        handled: true,
        response: new Response('Method Not Allowed', {
          status: 405,
          headers: { Allow: 'GET, HEAD' },
        }),
      };
    }

    const assetName = extra.path.slice(ASSET_PREFIX.length);
    const source = runtimeAssets[assetName];
    if (typeof source !== 'string') return result;

    const headers = {
      'Content-Type': assetName.endsWith('.css')
        ? 'text/css; charset=utf-8'
        : 'application/javascript; charset=utf-8',
      'Cache-Control': 'public, max-age=300',
      'X-Content-Type-Options': 'nosniff',
    };
    return {
      handled: true,
      response: new Response(extra.request?.method === 'HEAD' ? null : source, { headers }),
    };
  }, 5);

  // The client supports on-demand content detection or unconditional loading of enabled features.
  // The only content hook above protects TeX backslashes; Markdown parsing remains host-owned.
  addHook('archive:footer', pluginId, (html: string, extra?: { options?: Record<string, unknown> }) => {
    const config = featureConfig(extra?.options, pluginId);
    if (!config.math && !config.mermaid && !config.highlight && !config.blurhash) return html;
    const attrs = [
      config.math ? 'data-math="1"' : '',
      config.mermaid ? 'data-mermaid="1"' : '',
      config.highlight ? 'data-highlight="1"' : '',
      config.blurhash ? 'data-blurhash="1"' : '',
      config.blurhash && config.lazyImages ? 'data-lazy-images="1"' : '',
      `data-loading="${config.loadingMode}"`,
    ].filter(Boolean).join(' ');
    const preparedHtml = config.blurhash ? deferBlurhashImages(html) : html;
    return preparedHtml + `<script src="${ASSET_PREFIX}rehype-runtime.js" ${attrs} defer></script>`;
  }, 1000);
}
